export function asset(path: string) {
  return path.startsWith('/') ? path : `/${path}`;
}

export function cdn(id?: string, fallback = '/assets/default/default_alumet.jpg') {
  return id ? `/cdn/u/${id}` : fallback;
}

export function userAvatar(id?: string) {
  return cdn(id || 'defaultUser', '/cdn/u/defaultUser');
}

export function relativeTime(value?: string | number | Date) {
  if (!value) return 'Jamais';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return 'Date inconnue';

  const seconds = Math.round((date.getTime() - Date.now()) / 1000);
  const formatter = new Intl.RelativeTimeFormat('fr', { numeric: 'auto' });
  const units: Array<[Intl.RelativeTimeFormatUnit, number]> = [
    ['year', 31536000],
    ['month', 2592000],
    ['week', 604800],
    ['day', 86400],
    ['hour', 3600],
    ['minute', 60],
    ['second', 1]
  ];

  for (const [unit, amount] of units) {
    if (Math.abs(seconds) >= amount || unit === 'second') {
      return formatter.format(Math.round(seconds / amount), unit);
    }
  }

  return 'Maintenant';
}

export function appLabel(type?: string) {
  return {
    alumet: 'Alumet',
    flashcard: 'Flashcards',
    mindmap: 'Carte mentale'
  }[type || ''] || 'Application';
}

export function subjectLabel(subject?: string) {
  if (!subject) return 'Général';
  return subject.charAt(0).toUpperCase() + subject.slice(1);
}
