import { useParams } from 'react-router-dom';
import { api } from '../lib/api';
import { AlumetInfo } from '../types';
import { useAsync } from '../hooks/useAsync';
import { ErrorState, LoadingState } from '../components/State';
import BoardWorkspace from './workspace/BoardWorkspace';
import FlashcardsWorkspace from './workspace/FlashcardsWorkspace';
import MindmapWorkspace from './workspace/MindmapWorkspace';

export default function WorkspacePage() {
  const { applicationId } = useParams();
  const { data, loading, error, reload } = useAsync(() => api<{ infos: AlumetInfo }>(`/app/info/${applicationId}`), [applicationId]);

  if (loading) return <LoadingState label="Ouverture de l'espace..." />;
  if (error || !data) return <ErrorState message={error || 'Application introuvable'} />;

  if (data.infos.type === 'flashcard') {
    return <FlashcardsWorkspace app={data.infos} reloadInfo={reload} />;
  }
  if (data.infos.type === 'mindmap') {
    return <MindmapWorkspace app={data.infos} />;
  }
  return <BoardWorkspace app={data.infos} reloadInfo={reload} />;
}
