import { useMemo, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { ArrowLeft, Check, RotateCcw, X } from 'lucide-react';
import { api, postJson } from '../lib/api';
import { Flashcard, FlashcardSetInfo } from '../types';
import { useAsync } from '../hooks/useAsync';
import { ErrorState, LoadingState } from '../components/State';
import { useToast } from '../components/Toast';

export default function RevisionPage() {
  const { applicationId, mode = 'sandbox' } = useParams();
  const { notify } = useToast();
  const { data, loading, error, reload } = useAsync(
    () => api<{ flashcardSetInfo: FlashcardSetInfo }>(`/flashcards/${applicationId}/${mode}/content`),
    [applicationId, mode]
  );
  const cards = useMemo(() => data?.flashcardSetInfo.flashcards || [], [data]);
  const [index, setIndex] = useState(0);
  const [flipped, setFlipped] = useState(false);
  const current = cards[index];

  async function review(card: Flashcard, status: number) {
    if (!card._id) return;
    try {
      await postJson(`/flashcards/${applicationId}/${card._id}/review`, {
        status,
        cardReview: mode === 'smart'
      });
      setFlipped(false);
      setIndex(previous => Math.min(previous + 1, cards.length));
    } catch (err) {
      notify({ title: 'Révision impossible', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  if (loading) return <LoadingState label="Préparation de la révision..." />;
  if (error || !data) return <ErrorState message={error || 'Jeu introuvable'} />;

  return (
    <main className="revision-page">
      <header className="revision-header">
        <Link className="icon-button" to={`/app/${applicationId}`}>
          <ArrowLeft size={19} />
        </Link>
        <div>
          <span>{index}/{cards.length}</span>
          <h1>{data.flashcardSetInfo.title}</h1>
        </div>
        <button className="ghost-button" onClick={() => { setIndex(0); setFlipped(false); void reload(); }}>
          <RotateCcw size={17} />
          Recommencer
        </button>
      </header>

      {current ? (
        <section className={`revision-card ${flipped ? 'flipped' : ''}`} onClick={() => setFlipped(value => !value)}>
          <span>{flipped ? 'Réponse' : 'Question'}</span>
          <div dangerouslySetInnerHTML={{ __html: flipped ? current.answer : current.question }} />
        </section>
      ) : (
        <section className="revision-done">
          <h2>Session terminée</h2>
          <p>Bien joué. Tu peux recommencer ou retourner au jeu.</p>
        </section>
      )}

      {current && (
        <div className="revision-actions">
          <button className="ghost-button danger" onClick={() => review(current, 0)}>
            <X size={18} />
            À revoir
          </button>
          <button className="primary-button" onClick={() => review(current, 2)}>
            <Check size={18} />
            Je savais
          </button>
        </div>
      )}
    </main>
  );
}
