import { Link, useNavigate } from 'react-router-dom';
import { Bell, Brain, Columns3, LogOut, Network, Plus, ShieldCheck } from 'lucide-react';
import { api } from '../lib/api';
import { DashboardIdentity } from '../types';
import { useAsync } from '../hooks/useAsync';
import { AppCard } from '../components/AppCard';
import { EmptyState, ErrorState, LoadingState } from '../components/State';
import { userAvatar } from '../lib/format';

export default function DashboardPage() {
  const navigate = useNavigate();
  const { data, error, loading } = useAsync(() => api<DashboardIdentity>('/dashboard/identity'), []);

  if (loading) return <LoadingState label="Ouverture du dashboard..." />;
  if (error) {
    return <ErrorState message={error} action={<Link className="primary-button" to="/auth/signin">Se connecter</Link>} />;
  }
  if (!data) return null;

  return (
    <main className="app-shell">
      <aside className="sidebar">
        <Link to="/" className="brand">
          <img src="/assets/global/alumet.png" alt="" />
          <span>Alumet</span>
        </Link>
        <nav>
          <a className="active"><Columns3 size={18} /> Espaces</a>
          <a><Bell size={18} /> Invitations</a>
          <a><ShieldCheck size={18} /> Profil</a>
        </nav>
        <button className="ghost-button" onClick={() => (window.location.href = '/auth/logout')}>
          <LogOut size={17} />
          Déconnexion
        </button>
      </aside>

      <section className="dashboard-content">
        <header className="dashboard-header">
          <div>
            <span className="eyebrow">Bonjour {data.user.name}</span>
            <h1>Tes espaces de travail</h1>
          </div>
          <div className="profile-chip">
            <img src={userAvatar(data.user.icon)} alt="" />
            <div>
              <strong>{data.user.username || `${data.user.name} ${data.user.lastname || ''}`}</strong>
              <span>{data.user.mail}</span>
            </div>
          </div>
        </header>

        <div className="quick-actions">
          <button onClick={() => navigate('/app/setup/alumet')}>
            <Columns3 size={20} />
            Nouvel Alumet
          </button>
          <button onClick={() => navigate('/app/setup/flashcard')}>
            <Brain size={20} />
            Flashcards
          </button>
          <button onClick={() => navigate('/app/setup/mindmap')}>
            <Network size={20} />
            Carte mentale
          </button>
        </div>

        {data.invitations.length > 0 && (
          <section className="invite-strip">
            <h2>Invitations</h2>
            {data.invitations.slice(0, 3).map(invitation => (
              <Link to={`/invitation/${invitation.invitationId}`} key={invitation.invitationId}>
                <img src={userAvatar(invitation.icon)} alt="" />
                <span>{invitation.inviter} t'invite sur {invitation.applicationName}</span>
              </Link>
            ))}
          </section>
        )}

        <section className="cards-grid">
          {data.alumets.length ? (
            data.alumets.map(app => <AppCard app={app} key={app._id} />)
          ) : (
            <EmptyState title="Aucun espace pour le moment">
              Crée un Alumet, un jeu de flashcards ou une carte mentale pour commencer.
              <br />
              <Link className="primary-button inline-action" to="/app/setup/alumet">
                <Plus size={17} />
                Créer le premier
              </Link>
            </EmptyState>
          )}
        </section>
      </section>
    </main>
  );
}
