import { FormEvent, useState } from 'react';
import { Link, useNavigate, useParams, useSearchParams } from 'react-router-dom';
import { ArrowRight, Lock, Users } from 'lucide-react';
import { api, postJson } from '../lib/api';
import { AlumetInfo } from '../types';
import { useAsync } from '../hooks/useAsync';
import { cdn } from '../lib/format';
import { ErrorState, LoadingState } from '../components/State';
import { useToast } from '../components/Toast';

export default function PortalPage() {
  const { applicationId } = useParams();
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const { notify } = useToast();
  const [password, setPassword] = useState(params.get('password') || '');
  const { data, loading, error } = useAsync(() => api<{ infos: AlumetInfo; user_infos: unknown }>(`/app/info/${applicationId}`), [applicationId]);

  async function join(event: FormEvent) {
    event.preventDefault();
    try {
      await postJson(`/portal/authorize/${applicationId}`, { password });
      navigate(`/app/${applicationId}`);
    } catch (err) {
      notify({ title: 'Accès refusé', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  if (loading) return <LoadingState label="Vérification de l'accès..." />;
  if (error || !data) return <ErrorState message={error || 'Application introuvable'} />;

  const app = data.infos;
  if (app.participant) {
    navigate(`/app/${applicationId}`);
  }

  return (
    <main className="access-page">
      <section className="access-card">
        <img src={cdn(app.background)} alt="" />
        <div>
          <span className="eyebrow">
            <Users size={16} />
            Invitation à rejoindre
          </span>
          <h1>{app.title}</h1>
          <p>{app.description || 'Cet espace est prêt à être rejoint.'}</p>
          <form className="stack-form" onSubmit={join}>
            {app.security === 'onpassword' && (
              <label>
                Mot de passe
                <span>
                  <Lock size={17} />
                  <input value={password} onChange={event => setPassword(event.target.value)} autoFocus />
                </span>
              </label>
            )}
            {app.security === 'closed' ? (
              <Link className="ghost-button xl" to="/dashboard">Retour au dashboard</Link>
            ) : (
              <button className="primary-button xl">
                Rejoindre
                <ArrowRight size={18} />
              </button>
            )}
          </form>
        </div>
      </section>
    </main>
  );
}
