import { FormEvent, useEffect, useState } from 'react';
import { Plus, Trash2 } from 'lucide-react';
import { AlumetInfo } from '../../types';
import { WorkspaceChrome } from './WorkspaceChrome';

type NodeItem = {
  id: string;
  title: string;
  x: number;
  y: number;
};

export default function MindmapWorkspace({ app }: { app: AlumetInfo }) {
  const storageKey = `alumet:mindmap:${app._id}`;
  const [title, setTitle] = useState('');
  const [nodes, setNodes] = useState<NodeItem[]>(() => {
    const stored = window.localStorage.getItem(storageKey);
    return stored ? JSON.parse(stored) as NodeItem[] : [{ id: 'root', title: app.title, x: 48, y: 42 }];
  });

  useEffect(() => {
    window.localStorage.setItem(storageKey, JSON.stringify(nodes));
  }, [nodes, storageKey]);

  function addNode(event: FormEvent) {
    event.preventDefault();
    if (!title.trim()) return;
    setNodes(current => [
      ...current,
      {
        id: crypto.randomUUID(),
        title,
        x: 18 + Math.random() * 62,
        y: 18 + Math.random() * 58
      }
    ]);
    setTitle('');
  }

  return (
    <WorkspaceChrome
      app={app}
      actions={
        <form className="inline-form" onSubmit={addNode}>
          <input value={title} onChange={event => setTitle(event.target.value)} placeholder="Nouvelle idée" />
          <button className="icon-button">
            <Plus size={18} />
          </button>
        </form>
      }
    >
      <section className="mindmap-canvas">
        <svg viewBox="0 0 100 100" preserveAspectRatio="none">
          {nodes.slice(1).map(node => (
            <line key={node.id} x1={nodes[0].x} y1={nodes[0].y} x2={node.x} y2={node.y} />
          ))}
        </svg>
        {nodes.map(node => (
          <article className="mind-node" key={node.id} style={{ left: `${node.x}%`, top: `${node.y}%` }}>
            <span>{node.title}</span>
            {node.id !== 'root' && (
              <button onClick={() => setNodes(current => current.filter(item => item.id !== node.id))} aria-label="Supprimer">
                <Trash2 size={14} />
              </button>
            )}
          </article>
        ))}
      </section>
    </WorkspaceChrome>
  );
}
