import { FormEvent, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { ArrowRight, GraduationCap, Lock, Mail, UserRound } from 'lucide-react';
import { postJson } from '../lib/api';
import { useToast } from '../components/Toast';

type AuthMode = 'signin' | 'signup';

export default function AuthPage({ mode }: { mode: AuthMode }) {
  const navigate = useNavigate();
  const { notify } = useToast();
  const [loading, setLoading] = useState(false);
  const [needsCode, setNeedsCode] = useState(false);
  const [form, setForm] = useState({
    name: '',
    lastname: '',
    mail: '',
    password: '',
    accountType: 'student',
    code: ''
  });

  const isSignup = mode === 'signup';

  async function submit(event: FormEvent) {
    event.preventDefault();
    setLoading(true);
    try {
      if (needsCode) {
        await postJson('/auth/authorize', { mail: form.mail, code: form.code });
      } else {
        const response = await postJson<{ a2f?: boolean }>(`/auth/${mode}`, form);
        if (response.a2f) {
          setNeedsCode(true);
          notify({ title: 'Code envoyé', message: 'Vérifie ta boîte mail.', type: 'success' });
          return;
        }
      }
      navigate('/dashboard');
    } catch (error) {
      notify({ title: 'Connexion impossible', message: error instanceof Error ? error.message : undefined, type: 'error' });
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="auth-layout">
      <section className="auth-panel">
        <Link to="/" className="brand auth-brand">
          <img src="/assets/global/alumet.png" alt="" />
          <span>Alumet</span>
        </Link>
        <div>
          <span className="eyebrow">
            <GraduationCap size={16} />
            {isSignup ? 'Créer un compte' : 'Connexion'}
          </span>
          <h1>{needsCode ? 'Entre ton code de vérification' : isSignup ? 'Bienvenue dans Alumet.' : 'Content de te revoir.'}</h1>
          <p>
            {needsCode
              ? 'La double authentification protège ton espace de travail.'
              : 'Accède à tes classes, tes ressources et tes outils de révision.'}
          </p>
        </div>

        <form className="stack-form" onSubmit={submit}>
          {isSignup && !needsCode && (
            <div className="form-grid two">
              <label>
                Prénom
                <span>
                  <UserRound size={17} />
                  <input value={form.name} onChange={event => setForm({ ...form, name: event.target.value })} required minLength={2} />
                </span>
              </label>
              <label>
                Nom
                <span>
                  <UserRound size={17} />
                  <input value={form.lastname} onChange={event => setForm({ ...form, lastname: event.target.value })} required minLength={2} />
                </span>
              </label>
            </div>
          )}

          {!needsCode ? (
            <>
              <label>
                Adresse mail
                <span>
                  <Mail size={17} />
                  <input type="email" value={form.mail} onChange={event => setForm({ ...form, mail: event.target.value })} required />
                </span>
              </label>
              <label>
                Mot de passe
                <span>
                  <Lock size={17} />
                  <input type="password" value={form.password} onChange={event => setForm({ ...form, password: event.target.value })} required minLength={6} />
                </span>
              </label>
              {isSignup && (
                <label>
                  Profil
                  <select value={form.accountType} onChange={event => setForm({ ...form, accountType: event.target.value })}>
                    <option value="student">Élève</option>
                    <option value="professor">Professeur</option>
                  </select>
                </label>
              )}
            </>
          ) : (
            <label>
              Code reçu par mail
              <span>
                <Lock size={17} />
                <input value={form.code} onChange={event => setForm({ ...form, code: event.target.value })} required inputMode="numeric" minLength={6} maxLength={6} />
              </span>
            </label>
          )}

          <button className="primary-button xl" disabled={loading}>
            {loading ? 'Patiente...' : needsCode ? 'Valider le code' : isSignup ? 'Créer mon compte' : 'Se connecter'}
            <ArrowRight size={18} />
          </button>
        </form>

        <p className="switch-auth">
          {isSignup ? 'Déjà inscrit ?' : 'Pas encore de compte ?'}{' '}
          <Link to={isSignup ? '/auth/signin' : '/auth/signup'}>{isSignup ? 'Se connecter' : "S'inscrire"}</Link>
        </p>
      </section>
      <aside className="auth-visual">
        <div>
          <h2>Apprendre ensemble sans friction.</h2>
          <p>Un dashboard clair, des outils rapides, des invitations simples.</p>
        </div>
      </aside>
    </main>
  );
}
