import { useNavigate, useParams } from 'react-router-dom';
import { Check, X } from 'lucide-react';
import { api } from '../lib/api';
import { AlumetInfo } from '../types';
import { useAsync } from '../hooks/useAsync';
import { cdn, relativeTime } from '../lib/format';
import { ErrorState, LoadingState } from '../components/State';
import { useToast } from '../components/Toast';

export default function InvitationPage() {
  const { applicationId } = useParams();
  const navigate = useNavigate();
  const { notify } = useToast();
  const { data, loading, error } = useAsync(() => api<{ infos: AlumetInfo }>(`/app/info/${applicationId}`), [applicationId]);

  async function answer(kind: 'accept' | 'decline') {
    try {
      await api(`/invitation/${kind}/${applicationId}`, { method: 'POST' });
      notify({ title: kind === 'accept' ? 'Invitation acceptée' : 'Invitation refusée', type: 'success' });
      navigate('/dashboard');
    } catch (err) {
      notify({ title: 'Action impossible', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  if (loading) return <LoadingState label="Chargement de l'invitation..." />;
  if (error || !data) return <ErrorState message={error || 'Invitation introuvable'} />;

  return (
    <main className="access-page">
      <section className="access-card">
        <img src={cdn(data.infos.background)} alt="" />
        <div>
          <span className="eyebrow">Invitation · {relativeTime(data.infos.createdAt)}</span>
          <h1>{data.infos.title}</h1>
          <p>{data.infos.description || 'Tu as été invité à collaborer dans cet espace.'}</p>
          <div className="button-row">
            <button className="primary-button xl" onClick={() => answer('accept')}>
              <Check size={18} />
              Accepter
            </button>
            <button className="ghost-button xl danger" onClick={() => answer('decline')}>
              <X size={18} />
              Refuser
            </button>
          </div>
        </div>
      </section>
    </main>
  );
}
