import { ArrowRight, Brain, Columns3, Network } from 'lucide-react';
import { Link } from 'react-router-dom';
import { AlumetInfo } from '../types';
import { appLabel, cdn, relativeTime, subjectLabel } from '../lib/format';

const iconByType = {
  alumet: Columns3,
  flashcard: Brain,
  mindmap: Network
};

export function AppCard({ app }: { app: AlumetInfo }) {
  const Icon = iconByType[app.type] || Columns3;

  return (
    <Link to={`/app/${app._id}`} className="app-card">
      <img src={cdn(app.background)} alt="" />
      <div className="app-card-body">
        <span className="pill">
          <Icon size={14} />
          {appLabel(app.type)}
        </span>
        <h3>{app.title}</h3>
        <p>{app.description || subjectLabel(app.subject)}</p>
        <footer>
          <span>{relativeTime(app.lastUsage)}</span>
          <ArrowRight size={17} />
        </footer>
      </div>
    </Link>
  );
}
