import { FormEvent, useEffect, useState } from 'react';
import { Plus, Send, Trash2 } from 'lucide-react';
import { io } from 'socket.io-client';
import { api, putJson } from '../../lib/api';
import { AlumetInfo, Wall } from '../../types';
import { useAsync } from '../../hooks/useAsync';
import { EmptyState, ErrorState, LoadingState } from '../../components/State';
import { useToast } from '../../components/Toast';
import { userAvatar } from '../../lib/format';
import { WorkspaceChrome } from './WorkspaceChrome';

export default function BoardWorkspace({ app }: { app: AlumetInfo; reloadInfo: () => void }) {
  const { notify } = useToast();
  const { data, loading, error, reload, setData } = useAsync(() => api<{ walls: Wall[] }>(`/alumet/${app._id}/content`), [app._id]);
  const [wallTitle, setWallTitle] = useState('');
  const [drafts, setDrafts] = useState<Record<string, { title: string; content: string }>>({});

  useEffect(() => {
    const socket = io({ withCredentials: true });
    socket.emit('joinAlumet', app._id);
    socket.on('addWall', reload);
    socket.on('editWall', reload);
    socket.on('deleteWall', reload);
    socket.on('addPost', reload);
    socket.on('editPost', reload);
    socket.on('deletePost', reload);
    return () => {
      socket.disconnect();
    };
  }, [app._id, reload]);

  async function addWall(event: FormEvent) {
    event.preventDefault();
    if (!wallTitle.trim()) return;
    try {
      const wall = await putJson<Wall>(`/api/wall/${app._id}`, { title: wallTitle, postAuthorized: true });
      setData(current => ({ walls: [...(current?.walls || []), { ...wall, posts: [] }] }));
      setWallTitle('');
    } catch (err) {
      notify({ title: 'Mur impossible', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  async function addPost(event: FormEvent, wallId: string) {
    event.preventDefault();
    const draft = drafts[wallId];
    if (!draft?.title?.trim() && !draft?.content?.trim()) return;
    try {
      await putJson(`/api/post/${app._id}/${wallId}`, {
        title: draft.title,
        content: draft.content,
        postColor: 'white',
        commentAuthorized: true
      });
      setDrafts(current => ({ ...current, [wallId]: { title: '', content: '' } }));
      await reload();
    } catch (err) {
      notify({ title: 'Publication impossible', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  async function deletePost(postId: string) {
    try {
      await api(`/api/post/${app._id}/${postId}`, { method: 'DELETE' });
      await reload();
    } catch (err) {
      notify({ title: 'Suppression impossible', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  return (
    <WorkspaceChrome
      app={app}
      actions={
        <form className="inline-form" onSubmit={addWall}>
          <input value={wallTitle} onChange={event => setWallTitle(event.target.value)} placeholder="Nouveau mur" />
          <button className="icon-button" aria-label="Ajouter un mur">
            <Plus size={18} />
          </button>
        </form>
      }
    >
      {loading && <LoadingState label="Chargement des murs..." />}
      {error && <ErrorState message={error} />}
      {!loading && !error && (
        <section className="wall-board">
          {data?.walls?.length ? (
            data.walls.map(wall => {
              const draft = drafts[wall._id] || { title: '', content: '' };
              return (
                <article className="wall-column" key={wall._id}>
                  <header>
                    <h2>{wall.title}</h2>
                    <span>{wall.posts?.length || 0}</span>
                  </header>
                  <form className="post-composer" onSubmit={event => addPost(event, wall._id)}>
                    <input
                      placeholder="Titre"
                      value={draft.title}
                      onChange={event => setDrafts(current => ({ ...current, [wall._id]: { ...draft, title: event.target.value } }))}
                    />
                    <textarea
                      placeholder="Ajouter une ressource, une consigne, une idée..."
                      value={draft.content}
                      onChange={event => setDrafts(current => ({ ...current, [wall._id]: { ...draft, content: event.target.value } }))}
                    />
                    <button className="primary-button">
                      <Send size={16} />
                      Publier
                    </button>
                  </form>
                  <div className="post-list">
                    {wall.posts?.map(post => (
                      <article className="post-card" key={post._id}>
                        <div className="post-owner">
                          <img src={userAvatar(post.owner?.icon)} alt="" />
                          <span>{post.owner?.username || post.owner?.name || 'Invité'}</span>
                          {(post.editable || app.participant) && (
                            <button onClick={() => deletePost(post._id)} aria-label="Supprimer">
                              <Trash2 size={15} />
                            </button>
                          )}
                        </div>
                        {post.title && <h3>{post.title}</h3>}
                        {post.content && <div className="rich-content" dangerouslySetInnerHTML={{ __html: post.content }} />}
                        {post.file && <a className="mini-file" href={`/viewer/${post.file._id}`}>{post.file.displayname}</a>}
                      </article>
                    ))}
                  </div>
                </article>
              );
            })
          ) : (
            <EmptyState title="Aucun mur">
              Ajoute un premier mur pour structurer cet espace.
            </EmptyState>
          )}
        </section>
      )}
    </WorkspaceChrome>
  );
}
