import { FormEvent, useMemo, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowRight, ImagePlus } from 'lucide-react';
import { api } from '../lib/api';
import { useToast } from '../components/Toast';
import { TopBar } from '../components/TopBar';
import { AppType } from '../types';

const labels: Record<AppType, string> = {
  alumet: 'Alumet',
  flashcard: 'jeu de flashcards',
  mindmap: 'carte mentale'
};

export default function SetupPage() {
  const { type = 'alumet' } = useParams();
  const appType = (['alumet', 'flashcard', 'mindmap'].includes(type) ? type : 'alumet') as AppType;
  const navigate = useNavigate();
  const { notify } = useToast();
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string>('/assets/global/hands.jpg');
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({
    title: '',
    description: '',
    subject: 'general',
    security: 'open',
    chat: true
  });
  const title = useMemo(() => labels[appType], [appType]);

  function selectFile(nextFile?: File) {
    if (!nextFile) return;
    if (!nextFile.type.startsWith('image/') || nextFile.size > 3 * 1024 * 1024) {
      notify({ title: 'Image refusée', message: 'Choisis une image de moins de 3 Mo.', type: 'error' });
      return;
    }
    setFile(nextFile);
    setPreview(URL.createObjectURL(nextFile));
  }

  async function submit(event: FormEvent) {
    event.preventDefault();
    setLoading(true);
    const body = new FormData();
    if (file) body.append('file', file);
    body.append('title', form.title);
    body.append('description', form.description);
    body.append('subject', form.subject);
    body.append('security', form.security);
    body.append('chat', String(form.chat));
    body.append('type', appType);

    try {
      const response = await api<{ alumet: { _id: string } }>('/app/new', { method: 'PUT', body });
      notify({ title: 'Créé', message: `Ton ${title} est prêt.`, type: 'success' });
      navigate(`/app/${response.alumet._id}`);
    } catch (error) {
      notify({ title: 'Création impossible', message: error instanceof Error ? error.message : undefined, type: 'error' });
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="page-shell">
      <TopBar compact />
      <section className="setup-layout">
        <div>
          <span className="eyebrow">Nouvel espace</span>
          <h1>Créer un {title}</h1>
          <p>Une base claire maintenant évite les espaces confus plus tard. Choisis un titre lisible et une image reconnaissable.</p>
        </div>
        <form className="setup-card stack-form" onSubmit={submit}>
          <label className="cover-picker">
            <img src={preview} alt="" />
            <input type="file" accept="image/png,image/jpeg" onChange={event => selectFile(event.target.files?.[0])} />
            <span>
              <ImagePlus size={18} />
              Changer l'image
            </span>
          </label>
          <label>
            Nom
            <input value={form.title} onChange={event => setForm({ ...form, title: event.target.value })} required minLength={2} maxLength={80} />
          </label>
          <label>
            Description
            <textarea value={form.description} onChange={event => setForm({ ...form, description: event.target.value })} rows={4} />
          </label>
          <div className="form-grid two">
            <label>
              Matière
              <select value={form.subject} onChange={event => setForm({ ...form, subject: event.target.value })}>
                <option value="general">Général</option>
                <option value="maths">Mathématiques</option>
                <option value="science">Sciences</option>
                <option value="history">Histoire</option>
                <option value="language">Langues</option>
              </select>
            </label>
            <label>
              Accès
              <select value={form.security} onChange={event => setForm({ ...form, security: event.target.value })}>
                <option value="open">Ouvert</option>
                <option value="onpassword">Mot de passe</option>
                <option value="closed">Fermé</option>
              </select>
            </label>
          </div>
          <button className="primary-button xl" disabled={loading}>
            {loading ? 'Création...' : 'Créer'}
            <ArrowRight size={18} />
          </button>
        </form>
      </section>
    </main>
  );
}
