import { Navigate, Route, Routes } from 'react-router-dom';
import { ToastProvider } from './components/Toast';
import AuthPage from './pages/AuthPage';
import DashboardPage from './pages/DashboardPage';
import InvitationPage from './pages/InvitationPage';
import LandingPage from './pages/LandingPage';
import NotFoundPage from './pages/NotFoundPage';
import PortalPage from './pages/PortalPage';
import RevisionPage from './pages/RevisionPage';
import SetupPage from './pages/SetupPage';
import ViewerPage from './pages/ViewerPage';
import WorkspacePage from './pages/WorkspacePage';

export default function App() {
  return (
    <ToastProvider>
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/auth/signin" element={<AuthPage mode="signin" />} />
        <Route path="/auth/signup" element={<AuthPage mode="signup" />} />
        <Route path="/dashboard" element={<DashboardPage />} />
        <Route path="/app/setup/:type" element={<SetupPage />} />
        <Route path="/app/:applicationId" element={<WorkspacePage />} />
        <Route path="/portal/:applicationId" element={<PortalPage />} />
        <Route path="/invitation/:applicationId" element={<InvitationPage />} />
        <Route path="/flashcards/revise/:mode/:applicationId" element={<RevisionPage />} />
        <Route path="/viewer/:id" element={<ViewerPage />} />
        <Route path="/404" element={<NotFoundPage />} />
        <Route path="/main" element={<Navigate to="/" replace />} />
        <Route path="*" element={<NotFoundPage />} />
      </Routes>
    </ToastProvider>
  );
}
