import { FormEvent, useMemo, useState } from 'react';
import { BookOpen, Plus, RotateCcw, Save, Sparkles, Trash2 } from 'lucide-react';
import { Link } from 'react-router-dom';
import { api, postJson } from '../../lib/api';
import { AlumetInfo, Flashcard, FlashcardSetInfo } from '../../types';
import { useAsync } from '../../hooks/useAsync';
import { EmptyState, ErrorState, LoadingState } from '../../components/State';
import { useToast } from '../../components/Toast';
import { WorkspaceChrome } from './WorkspaceChrome';

export default function FlashcardsWorkspace({ app }: { app: AlumetInfo; reloadInfo: () => void }) {
  const { notify } = useToast();
  const { data, loading, error, reload, setData } = useAsync(
    () => api<{ flashcardSetInfo: FlashcardSetInfo }>(`/flashcards/${app._id}/sandbox/content`),
    [app._id]
  );
  const cards = data?.flashcardSetInfo.flashcards || [];
  const [draft, setDraft] = useState<Flashcard>({ question: '', answer: '' });
  const [aiPrompt, setAiPrompt] = useState('');
  const stats = useMemo(() => {
    const learned = cards.filter(card => (card.userDatas?.status || 0) >= 2).length;
    return { learned, total: cards.length };
  }, [cards]);

  async function saveCards(nextCards: Flashcard[]) {
    const response = await postJson<{ flashcards: Flashcard[] }>(`/flashcards/${app._id}/check`, {
      flashcardSetId: app._id,
      flashcards: nextCards
    });
    setData(current => current ? { flashcardSetInfo: { ...current.flashcardSetInfo, flashcards: response.flashcards } } : current);
  }

  async function addCard(event: FormEvent) {
    event.preventDefault();
    if (!draft.question.trim() || !draft.answer.trim()) return;
    try {
      await saveCards([...cards, draft]);
      setDraft({ question: '', answer: '' });
      notify({ title: 'Carte ajoutée', type: 'success' });
    } catch (err) {
      notify({ title: 'Sauvegarde impossible', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  async function deleteCard(card: Flashcard) {
    if (!card._id) return;
    try {
      await api(`/flashcards/${app._id}/${card._id}`, { method: 'DELETE' });
      await reload();
    } catch (err) {
      notify({ title: 'Suppression impossible', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  async function generateAi() {
    if (!aiPrompt.trim()) return;
    try {
      const response = await postJson<{ flashcards: Flashcard[]; message?: string }>('/openai/flashcards/generate-flashcards', {
        generationMode: 'keywords',
        numberOfFlashcards: 12,
        subject: 'other',
        data: aiPrompt
      });
      if (!response.flashcards.length) {
        notify({ title: 'Aucune carte générée', message: response.message, type: 'error' });
        return;
      }
      await saveCards([...cards, ...response.flashcards]);
      setAiPrompt('');
      notify({ title: 'Cartes générées', message: `${response.flashcards.length} nouvelles cartes.`, type: 'success' });
    } catch (err) {
      notify({ title: 'IA indisponible', message: err instanceof Error ? err.message : undefined, type: 'error' });
    }
  }

  return (
    <WorkspaceChrome
      app={app}
      actions={
        <div className="button-row">
          <Link className="ghost-button" to={`/flashcards/revise/sandbox/${app._id}`}>
            <BookOpen size={17} />
            Réviser
          </Link>
          <button className="ghost-button" onClick={() => reload()}>
            <RotateCcw size={17} />
            Recharger
          </button>
        </div>
      }
    >
      {loading && <LoadingState label="Chargement des flashcards..." />}
      {error && <ErrorState message={error} />}
      {!loading && !error && (
        <section className="flashcards-layout">
          <aside className="study-panel">
            <span className="eyebrow">Progression</span>
            <h2>{stats.learned}/{stats.total}</h2>
            <p>Cartes déjà maîtrisées ou presque.</p>
            <textarea value={aiPrompt} onChange={event => setAiPrompt(event.target.value)} placeholder="Sujet, mots-clés ou notions pour générer des cartes..." />
            <button className="primary-button" onClick={generateAi}>
              <Sparkles size={17} />
              Générer avec l'IA
            </button>
          </aside>

          <section className="flashcards-editor">
            <form className="card-editor" onSubmit={addCard}>
              <input value={draft.question} onChange={event => setDraft({ ...draft, question: event.target.value })} placeholder="Question" />
              <textarea value={draft.answer} onChange={event => setDraft({ ...draft, answer: event.target.value })} placeholder="Réponse" />
              <button className="primary-button">
                <Plus size={17} />
                Ajouter
              </button>
            </form>

            <div className="flashcard-list">
              {cards.length ? (
                cards.map((card, index) => (
                  <article className="flashcard-row" key={card._id || index}>
                    <div>
                      <strong dangerouslySetInnerHTML={{ __html: card.question }} />
                      <p dangerouslySetInnerHTML={{ __html: card.answer }} />
                    </div>
                    <button onClick={() => deleteCard(card)} aria-label="Supprimer">
                      <Trash2 size={16} />
                    </button>
                  </article>
                ))
              ) : (
                <EmptyState title="Aucune flashcard">
                  Ajoute une carte manuellement ou génère une première série.
                </EmptyState>
              )}
            </div>
          </section>
        </section>
      )}
    </WorkspaceChrome>
  );
}
